CREATE TABLE IF NOT EXISTS fee_structures (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), fee_type TEXT NOT NULL, amount REAL NOT NULL, academic_year_id TEXT REFERENCES academic_years(id), term_id TEXT REFERENCES terms(id), class_id TEXT REFERENCES classes(id), student_id TEXT REFERENCES student_profiles(id), boarding_type TEXT, optional_service TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), invoice_number TEXT NOT NULL UNIQUE, student_id TEXT NOT NULL REFERENCES student_profiles(id), parent_user_id TEXT REFERENCES users(id), line_items_json TEXT NOT NULL, discount REAL NOT NULL DEFAULT 0, total REAL NOT NULL, paid REAL NOT NULL DEFAULT 0, balance REAL NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), receipt_number TEXT NOT NULL UNIQUE, invoice_id TEXT NOT NULL REFERENCES invoices(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), amount REAL NOT NULL, payment_method TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'VALID', entered_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, changed_by TEXT REFERENCES users(id), changed_at TEXT, change_reason TEXT);
CREATE TABLE IF NOT EXISTS payment_gateway_configs (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), provider TEXT NOT NULL, public_config_json TEXT NOT NULL, secret_key_setting TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS financial_adjustments (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), adjustment_type TEXT NOT NULL, amount REAL NOT NULL, reason TEXT, authorized_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_invoices_student ON invoices(school_id, student_id);
CREATE INDEX IF NOT EXISTS idx_payments_student ON payments(school_id, student_id);
